import React, { useId, useLayoutEffect, useRef } from "react";

const bodyScrollLocks = new WeakMap();

function lockBodyScroll(body) {
  let lock = bodyScrollLocks.get(body);

  if (!lock) {
    lock = {
      count: 0,
      overflow: body.style.overflow,
      priority: body.style.getPropertyPriority("overflow"),
    };
    bodyScrollLocks.set(body, lock);
  }

  lock.count += 1;
  body.style.overflow = "hidden";

  let released = false;

  return () => {
    if (released) return;
    released = true;

    lock.count -= 1;

    if (lock.count === 0) {
      bodyScrollLocks.delete(body);
      body.style.setProperty("overflow", lock.overflow, lock.priority);
    }
  };
}

function getFocusableElements(dialog) {
  return Array.from(
    dialog.querySelectorAll(
      "a[href], button, input, select, textarea, [tabindex]"
    )
  ).filter(
    (element) =>
      !element.matches(":disabled") &&
      !(element.localName === "input" && element.type === "hidden") &&
      (!element.hasAttribute("tabindex") || element.tabIndex !== -1)
  );
}

export function Dialog({ open, onClose, title, children }) {
  const titleId = useId();
  const dialogRef = useRef(null);
  const backdropRef = useRef(null);
  const pressedOnBackdropRef = useRef(false);

  useLayoutEffect(() => {
    if (!open) return;

    const dialog = dialogRef.current;
    const backdrop = backdropRef.current;
    if (!dialog || !backdrop) return;

    const doc = dialog.ownerDocument;
    const body = doc.body;
    const previouslyFocused = doc.activeElement;
    const releaseScrollLock = lockBodyScroll(body);

    pressedOnBackdropRef.current = false;

    // Capture presses anywhere, including descendants that stop propagation.
    const rememberPress = (event) => {
      pressedOnBackdropRef.current = event.target === backdrop;
    };

    doc.addEventListener("mousedown", rememberPress, true);

    const initialTarget =
      dialog.querySelector("[data-autofocus]") ||
      getFocusableElements(dialog)[0] ||
      dialog;

    if (typeof initialTarget.focus === "function") {
      initialTarget.focus();
    } else {
      dialog.focus();
    }

    return () => {
      doc.removeEventListener("mousedown", rememberPress, true);
      pressedOnBackdropRef.current = false;
      releaseScrollLock();

      if (
        previouslyFocused &&
        previouslyFocused !== body &&
        doc.contains(previouslyFocused) &&
        typeof previouslyFocused.focus === "function"
      ) {
        previouslyFocused.focus();
      }
    };
  }, [open]);

  const handleKeyDown = (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      if (!event.repeat) onClose();
      return;
    }

    if (event.key !== "Tab") return;

    const dialog = event.currentTarget;
    const focusableElements = getFocusableElements(dialog);

    if (focusableElements.length === 0) {
      event.preventDefault();
      dialog.focus();
      return;
    }

    const first = focusableElements[0];
    const last = focusableElements[focusableElements.length - 1];
    const activeElement = dialog.ownerDocument.activeElement;
    const shouldWrap = event.shiftKey
      ? activeElement === first
      : activeElement === last;

    if (
      activeElement === dialog ||
      !focusableElements.includes(activeElement) ||
      shouldWrap
    ) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    }
  };

  const handleBackdropClick = (event) => {
    const pressedOnBackdrop = pressedOnBackdropRef.current;
    pressedOnBackdropRef.current = false;

    if (pressedOnBackdrop && event.target === event.currentTarget) {
      onClose();
    }
  };

  if (!open) return null;

  return (
    <div
      data-testid="backdrop"
      ref={backdropRef}
      onClick={handleBackdropClick}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        onKeyDownCapture={handleKeyDown}
      >
        <h2 id={titleId}>{title}</h2>
        {children}
      </div>
    </div>
  );
}
